#include <limits.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

int next_capacity(size_t current, size_t needed, size_t elem, size_t *out)
{
    if (elem == 0) return -1;
    size_t limit = SIZE_MAX / elem;
    if (needed > limit) return -1;
    size_t cap = current ? current : 8;
    while (cap < needed) cap = cap > limit / 2 ? limit : cap * 2;
    if (cap > limit) cap = limit;
    *out = cap;
    return 0;
}

void *alloc_records(size_t count, size_t elem, size_t header)
{
    if (elem != 0 && count > SIZE_MAX / elem) return NULL;
    size_t body = count * elem;
    if (body > SIZE_MAX - header) return NULL;
    return malloc(header + body);
}

int to_int(long long v, int *out)
{
    if (v < INT_MIN || v > INT_MAX) return 0;
    *out = (int)v;
    return 1;
}

int midpoint(int a, int b)
{
    long long sum = (long long)a + b;
    long long m = sum / 2;
    if (sum < 0 && sum % 2 != 0) m -= 1;
    return (int)m;
}

unitTests:
TEST("capacities double") { size_t c = 0; CHECK_EQ(next_capacity(0, 1, 4, &c), 0); CHECK_EQ((int)c, 8); CHECK_EQ(next_capacity(8, 9, 4, &c), 0); CHECK_EQ((int)c, 16); CHECK_EQ(next_capacity(16, 100, 4, &c), 0); CHECK_EQ((int)c, 128); }
TEST("capacities never overflow") { size_t c = 0; CHECK_EQ(next_capacity(SIZE_MAX / 8, SIZE_MAX / 8 + 1, 4, &c), 0); CHECK(c >= SIZE_MAX / 8 + 1 && c <= SIZE_MAX / 4); CHECK_EQ(next_capacity(SIZE_MAX / 4 - 5, SIZE_MAX / 4, 4, &c), 0); CHECK(c == SIZE_MAX / 4); CHECK_EQ(next_capacity(0, SIZE_MAX / 4 + 1, 4, &c), -1); CHECK_EQ(next_capacity(0, 1, 0, &c), -1); }
TEST("allocation sizes are checked") { void *p = alloc_records(10, 16, 8); CHECK(p != NULL); free(p); CHECK(alloc_records(SIZE_MAX / 8, 16, 0) == NULL); CHECK(alloc_records(SIZE_MAX / 16, 16, 64) == NULL); }
TEST("to_int") { int x = 5; CHECK_EQ(to_int(123, &x), 1); CHECK_EQ(x, 123); CHECK_EQ(to_int(5000000000LL, &x), 0); CHECK_EQ(to_int(INT_MIN, &x), 1); CHECK_EQ(x, INT_MIN); }
TEST("midpoint") { CHECK_EQ(midpoint(2, 4), 3); CHECK_EQ(midpoint(INT_MAX, INT_MAX - 2), INT_MAX - 1); CHECK_EQ(midpoint(INT_MIN, INT_MIN), INT_MIN); CHECK_EQ(midpoint(-3, 0), -2); CHECK_EQ(midpoint(3, 0), 1); CHECK_EQ(midpoint(INT_MIN, INT_MAX), -1); }

